/**
 * One cache key per shared navigation script across every published page.
 *
 * Pages are generated by many renderers, and some still carry older ?v= strings for the shared
 * global-nav scripts (site-chrome.js, lang-nav.js). Mixed keys let a browser reuse an older cached
 * copy on some pages while others load the current file — the menu then looks or behaves
 * differently from page to page. This pass rewrites only those query strings in the published
 * HTML; file contents and page markup are untouched.
 *
 * Usage: node scripts/normalize-asset-versions.mjs --root _publish
 */
import fs from "fs";
import path from "path";

export const SHARED_ASSET_VERSIONS = {
  "site-chrome.js": "20261019nav10",
  "lang-nav.js": "20261019ln1",
};

export function normalizeAssetVersions(html) {
  let out = html;
  for (const [file, ver] of Object.entries(SHARED_ASSET_VERSIONS)) {
    const re = new RegExp(`(["'/])${file.replace(/\./g, "\\.")}\\?v=[A-Za-z0-9._-]+`, "g");
    out = out.replace(re, `$1${file}?v=${ver}`);
  }
  return out;
}

function walk(dir, acc) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === "node_modules" || e.name.startsWith(".")) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (e.name.endsWith(".html")) acc.push(p);
  }
  return acc;
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname);
if (isMain) {
  const i = process.argv.indexOf("--root");
  const root = path.resolve(i > -1 ? process.argv[i + 1] : "_publish");
  let changed = 0;
  for (const f of walk(root, [])) {
    const src = fs.readFileSync(f, "utf8");
    const out = normalizeAssetVersions(src);
    if (out !== src) {
      fs.writeFileSync(f, out, "utf8");
      changed++;
    }
  }
  console.log(`normalize-asset-versions: ${changed} pages updated under ${path.relative(process.cwd(), root) || "."}`);
}
